// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2020, "8-9", [{"author":"И. Рубанов","question":"<em>Старый друг лучше новых</em> … .","choices":["<em>двух</em>","<em>трёх</em>","<em>четырёх</em>","<em>пяти</em>","<em>брюк</em>."],"key":"А","review":["Пословица о дружбе","Пословица сравнивает одного проверенного друга с несколькими новыми. Ищи устойчивое продолжение.","Говорят «Старый друг лучше новых двух». В пропуске «двух»."]},{"author":"Е. Бикмаев","question":"Какое из этих слов часто можно встретить в прогнозе погоды?","choices":["<em>однозначно</em>","<em>понятно</em>","<em>ясно</em>","<em>неясно</em>","<em>неопределённо</em>."],"key":"В","review":["Слово в прогнозе","Метеоролог может описать количество облаков словом из списка. Сравни выражения «ясная погода» и «ясное небо».","В прогнозе говорят «завтра ясно». Здесь «ясно» значит «без облаков»."]},{"author":"Е. Бикмаев","question":"Слово <em>просьба</em> иностранцу можно объяснить так: «Это когда просят». А какое слово так не объяснишь?","choices":["<em>косьба</em>","<em>молотьба</em>","<em>мольба</em>","<em>судьба</em>","<em>ходьба.</em>"],"key":"Г","review":["Названия действий","Косьба — когда косят, молотьба — когда молотят, мольба — когда молят, ходьба — когда ходят.","«Судьба» означает жизненный путь или то, что кому-то выпало. В современном языке это не название действия «судить»."]},{"author":"С. Дьяченко","question":"Какое слово может быть синонимом слова <em>заботиться</em>?","choices":["<em>вариться</em>","<em>жариться</em>","<em>кипятиться</em>","<em>печься</em>","<em>тушиться</em>."],"key":"Г","review":["Слово о заботе","Речь идёт о поступках человека, который думает о благополучии другого. Ищи глагол с таким переносным значением.","«Печься о детях» значит «заботиться о детях». Это значение отличается от буквального «хлеб печётся»."]},{"author":"Б. Иомдин","question":"Какое выражение обычно не используется для подтверждения чего-либо?","choices":["<em>нет слов</em>","<em>и речи быть не может</em>","<em>о чём разговор</em>","<em>что и говорить</em>","<em>и не говори</em>."],"key":"Б","review":["Подтверждение или отказ","«Нет слов», «о чём разговор», «что и говорить» и «и не говори» могут показывать согласие с собеседником.","«И речи быть не может» обычно означает решительный отказ. Так исключают возможность чего-то."]},{"author":"Б. Иомдин","question":"Что бывает <em>тинистым</em>?","choices":["<em>аллея</em>","<em>парк</em>","<em>вода</em>","<em>возраст</em>","среди ответов (А)–(Г) нет правильного."],"key":"В","review":["Прилагательное «тинистый»","«Тенистый» — с обильной тенью. В вопросе другое слово: «тинистый», от «тина».","Тина бывает в воде. Тинистой может быть вода заросшего пруда."]},{"author":"Е. Бикмаев","question":"В каком предложении числительное существенно отличается по смыслу от числительных в других предложениях?","choices":["<em>Первая перепись в послереволюционной России была проведена в 1920 году.</em>","<em>Второй анализ не подтвердил подозрения врачей.</em>","<em>Третья группа в эксперименте была контрольной.</em>","<em>Четвёртый опыт позволил физику получить более точные результаты.</em>","<em>Пятая часть опрошенных не определилась с ответом.</em>"],"key":"Д","review":["Порядок и доля","Переписи, анализы, группы и опыты можно пронумеровать. Числительное в каждом из этих случаев указывает место в ряду.","«Пятая часть» — одна из пяти равных долей. Здесь числительное описывает величину доли и не указывает порядок."]},{"author":"И. Рубанов","question":"Когда Антон старается избавить Игоря от ответственности, говорят, что <em>Антон … Игоря</em>. Какое слово должно стоять на месте многоточия?","choices":["<em>выгораживает</em>","<em>загораживает</em>","<em>огораживает</em>","<em>отгораживает</em>","ни одно из слов (А)–(Г) не подходит."],"key":"А","review":["Как скрывают вину","Огораживать, загораживать и отгораживать обычно означает ставить преграду или заслонять.","«Выгораживать» переносно значит защищать виноватого, оправдывать или скрывать его вину. Это и делает Антон."]},{"author":"О. Подлесская","question":"Какое слово не связано с приготовлением и приёмом пищи?","choices":["<em>трапезная</em>","<em>опочивальня</em>","<em>столовая</em>","<em>потчевать</em>","<em>стряпать</em>."],"key":"Б","review":["Где едят и где спят","Трапезная и столовая — места для еды. Потчевать значит угощать, стряпать — готовить пищу.","Опочивальня — спальня. Её название связано с отдыхом и сном."]},{"author":"А. Пиперски","question":"В каком слове <em>кое</em>- выражает не тот смысл, что в остальных?","choices":["<em>кое-где</em>","<em>кое-куда</em>","<em>кое-как</em>","<em>кое-что</em>","<em>кое-какой</em>."],"key":"В","review":["Два значения «кое-»","В «кое-где», «кое-куда», «кое-что» и «кое-какой» часть «кое-» указывает, что место, предмет или признак не называют точно.","«Кое-как» обычно значит «небрежно», «едва справившись». Здесь речь о качестве выполнения, а не просто о неизвестном способе."]},{"author":"И. Рубанов","question":"Русские названия скольких дней недели произведены от числительных?","choices":["одного","двух","трёх","четырёх","пяти."],"key":"В","review":["Числительные в днях недели","Вторник связан со словом «второй», четверг — с «четвёртый», пятница — с «пятый».","У среды название связано с серединой недели, а у остальных дней происхождение другое. Получается три названия от числительных."]},{"author":"И. Иткин","question":"В переводе одного романа встретилась такая фраза: «Одеяние второго [карлика] наводило на мысль о сбежавшем из театра если не Али-Бабе, то кого-то из его сорока разбойников». Какую форму местоимения <em>кто-то</em> должен был употребить переводчик?","choices":["<em>кто-то</em>","<em>кому-то</em>","<em>кем-то</em>","<em>ком-то</em>","переводчик правильно употребил форму <em>кого-то</em>."],"key":"Г","review":["Падеж после «о»","«О сбежавшем ... Али-Бабе» отвечает на вопрос «о ком?». После «если не ..., то ...» второй вариант должен отвечать на тот же вопрос.","Правильно «если не об Али-Бабе, то о ком-то из его разбойников». Нужная форма — «ком-то»."]},{"author":"Е. Муравенко","question":"В каком из сочетаний глагол <em>проводить</em> относится к совершенному виду?","choices":["<em>проводить друга в аэропорт</em>","<em>весело проводить время</em>","<em>проводить игру-конкурс «Русский медвежонок»</em>","<em>проводить интернет</em>","во всех сочетаниях глагол <em>проводить</em> относится к одному и тому же виду."],"key":"А","review":["Значения «проводить»","«Проводить» время, игру или интернет можно как длительное или повторяющееся действие. Оно отвечает на вопрос «что делать?».","«Проводить друга в аэропорт» означает довести его до места и попрощаться. Здесь вопрос «что сделать?», поэтому вид совершенный."]},{"author":"П. Аркадьев","question":"<em>Большого внимания ... не уделяют</em>. Как правильно заполнить пропуск?","choices":["<em>к ним</em>","<em>на них</em>","<em>им</em>","<em>их</em>","<em>для них</em>."],"key":"В","review":["Кому уделяют внимание","У глагола можно спросить «уделяют что и кому?». При отрицании появляется конструкция «большого внимания», но второй вопрос остаётся прежним.","Нужен дательный падеж без предлога. Правильно «большого внимания им не уделяют»."]},{"author":"Е. Бикмаев","question":"В словаре «Астраханские словечки» приводится слово из речи рыбаков <em>бережне́е</em>. А какой у него антоним?","choices":["<em>рыби́стее</em>","<em>мори́стее</em>","<em>икри́стее</em>","<em>весли́стее</em>","<em>улови́стее</em>."],"key":"Б","review":["Слова рыбаков","«Бережне́е» в речи рыбаков связано с берегом. Оно означает направиться ближе к берегу или находиться с его стороны.","Обратное направление — дальше в море. Его передаёт слово «мори́стее»."]},{"author":"Б. Иомдин и И. Рубанов","question":"Какое слово в этом списке по смыслу отличается от остальных значительно сильнее, чем остальные <em>—</em> друг от друга?","choices":["<em>баскетболист</em>","<em>вокалист</em>","<em>остролист</em>","<em>скандалист</em>","<em>стилист</em>."],"key":"В","review":["Одинаковый конец слов","Баскетболист, вокалист, скандалист и стилист — названия людей. Здесь «-ист» выступает как суффикс.","«Остролист» — растение. В конце названия стоит слово «лист» в составе сложного слова."]},{"author":"С. Дьяченко","question":"В каком из этих наречий пропущена не та буква, что в остальных?","choices":["<em>кос_ком</em>","<em>обин_ком</em>","<em>особн_ком</em>","<em>порожн_ком</em>","<em>бос_ком</em>."],"key":"Д","review":["Гласная в наречиях","Восстанови данные наречия: «косяком», «обиняком», «особняком», «порожняком». В пропусках этих четырёх слов стоит Я.","В наречии «босиком» вместо Я нужна И. Оно отличается от остальных."]},{"author":"М. Рубинштейн","question":"Даны португальские слова: <em>autoescola</em> ‘автошкола’, <em>inter-racial</em> ‘межрасовый’, <em>semi-integração</em> ‘полуинтеграция’, <em>sub-brigadeiro</em> ‘полицейский сержант’, <em>subitem</em> ‘подпункт’, <em>internacional</em> ‘международный’. Как пишутся по-португальски переводы следующих слов: <em>гиперреальный</em>, <em>автооператор</em>, <em>полуоткрытый</em>?","choices":["hiperreal, autooperador, semiaberto","hiper-real, auto-operador, semi-aberto","hiper-real, auto-operador, semiaberto","hiperreal, autooperador, semi-aberto","hiper-real, autooperador, semiaberto."],"key":"В","review":["Дефис по-португальски","В «inter-racial» совпадают соседние r, в «sub-brigadeiro» — b, в «semi-integração» — i. При совпадении букв на границе частей ставят дефис.","Поэтому получаем «hiper-real» и «auto-operador» с одинаковыми буквами по обе стороны границы. У «semiaberto» соседи разные, дефиса нет."]},{"author":"Б. Иомдин","question":"Даны пять цитат из произведений А. С. Пушкина. В какой из них пропущены не те буквы, что в остальных?","choices":["<em>Лошадь ступала наудачу и поминутно т_ въезжала на сугроб, т_ проваливалась в яму.</em>","<em>Барыни дарили её, т_ платочком, т_ серёжками.</em>","<em>Парень вышел с дубиною и пошёл вперед, т_ указывая, т_ отыскивая дорогу.</em>","<em>Он был чрезвычайно весел, без умолку шутил т_ с Дунею, т_ с смотрителем.</em>","<em>Он посматривал с подозрением т_ на хозяина, т_ на вожатого.</em>"],"key":"Б","review":["«То» или «те»","При перечислении сменяющихся действий или направлений употребляют «то ..., то ...». Это подходит к лошади, парню, шуткам и взглядам.","Некоторые барыни подарили платочек, другие — серёжки. Здесь «те ... те ...» указывает на разных дарительниц, поэтому нужны буквы Е."]},{"author":"С. Сай","question":"В какой паре основные значения слов связаны друг с другом гораздо меньше, чем в других парах?","choices":["<em>удивление — удивлённый</em>","<em>приземление — приземлённый</em>","<em>искажение — искажённый</em>","<em>изучение — изученный</em>","<em>порабощение — порабощённый</em>."],"key":"Б","review":["Буквальное и переносное","«Удивлённый», «искажённый», «изученный» и «порабощённый» прямо относятся к результату названного в паре действия.","«Приземление» — посадка или прикосновение к земле. «Приземлённый» часто означает слишком практичный, чуждый высоких интересов. Пара расходится по смыслу."]},{"author":"А. Сомин","question":"Плавание вокруг мыса Дежнёва — крайней восточной точки России и всей Евразии — чрезвычайно опасно в плохую погоду, которая там нередка. На старых картах этот мыс обозначался как ___________ <em>Нос</em>. Какое слово мы пропустили?","choices":["<em>Незаменимый</em>","<em>Необходимый</em>","<em>Достаточный</em>","<em>Обязательный</em>","<em>Нужный</em>."],"key":"Б","review":["Старое название мыса","В старом названии «нос» означает мыс. Ищи прилагательное, в звучании которого можно услышать старую связь с «обойти».","На старых картах мыс Дежнёва называли «Необходимый Нос». Из списка подходит «Необходимый»."]},{"author":"И. Рубанов","question":"О человеке, который ходит с гордым видом, посматривая на всех свысока, говорят, что он <em>ходит</em> … .","choices":["<em>блоком</em>","<em>гоголем</em>","<em>пушкиным</em>","<em>толстым</em>","<em>фетом</em>."],"key":"Б","review":["Походка с важным видом","Устойчивое выражение сравнивает горделивую походку с видом птицы. «Гоголь» — водоплавающая птица.","«Ходить гоголем» значит держаться важно и самодовольно. Здесь «гоголь» — название птицы."]},{"author":"И. Рубанов","question":"<em>Кризис поразил Анчурию, а ... Руританию. Больше всего пострадала компания «Альфа», акции которой упали на 90%. ... сильно пострадали фирмы «Бета» и «Гамма», акции которых упали на 60% и 50% соответственно.</em> Как надо заполнить пробелы?","choices":["<em>также</em>, <em>также</em>","<em>так же</em>, <em>также</em>","<em>также</em>, <em>так же</em>","<em>так же</em>, <em>так же</em>","ни один из вариантов (А)–(Г) не подходит."],"key":"А","review":["Слитное и раздельное","«Также» можно заменить на «тоже», а «так же» значит «таким же способом» или «в той же степени». В первом пропуске называют вторую страну, которую тоже затронул кризис.","Во втором примере падение акций 60 % и 50 % отличается от 90 %. Речь о других фирмах, которые тоже сильно пострадали. Оба раза пишется «также»."]},{"author":"Е. Бикмаев","question":"Какие из слов <em>служащий</em>, <em>работящий</em>, <em>трудящийся</em>, <em>заведующий</em> не могут быть причастиями?","choices":["только <em>служащий</em>","только <em>работящий</em>","<em>служащий</em> и <em>работящий</em>","<em>работящий</em> и <em>трудящийся</em>","<em>служащий</em> и <em>заведующий</em>."],"key":"Б","review":["Глагол и причастие","К причастию можно задать вопрос «что делающий?» и найти глагол: «служащий», «трудящийся», «заведующий».","«Работящий» означает трудолюбивый, охотно работающий. Причастие от «работать» — «работающий», поэтому «работящий» только прилагательное."]},{"author":"Б. Иомдин","question":"Представим себе игру: вам говорят слово, а вы угадываете, какое слово в тексте идёт следующим. С каким словом, сказанным вам, у вас наибольший шанс выиграть?","choices":["<em>всегда</em>","<em>иногда</em>","<em>когда</em>","<em>тогда</em>","<em>никогда</em>."],"key":"Д","review":["Угадай следующее слово","После многих наречий подходят разные слова. Ищи наречие, которое в русском предложении особенно часто предваряет частицу отрицания.","«Никогда» регулярно сочетается с «не»: «никогда не забуду», «никогда не видел». Это повышает шанс угадать следующее слово."]},{"author":"С. Дьяченко","question":"По мнению ряда учёных, одно из значений некоторого глагола появилось из-за представлений о колдовстве: колдуны разбрасывали некий продукт, предварительно произнеся над ним заклинание. Человек, который наступал на то, что было рассыпано, подвергался «порче». Что рассыпали колдуны?","choices":["<em>перец</em>","<em>муку</em>","<em>горох</em>","<em>сахар</em>","<em>соль</em>."],"key":"Д","review":["Слово о колдовстве","Сравни «насолить» в прямом значении и разговорное «насолить кому-то», причинить неприятность.","С гипотезой о порче связано переносное значение. В таком рассказе колдуны рассыпали соль."]},{"author":"И. Иткин","question":"Выступая с совместными статьями, учёный-экономист Н. Ф. Анненский и писатель В. Г. Короленко печатали их под псевдонимом «О. _ А.».","choices":["А.","Б.","В.","Г.","Д."],"key":"Б","review":["Совместная подпись","В псевдониме участвуют двое авторов. Ищи букву, которая превратит инициалы в слово о двух людях.","Из «О. Б. А.» получается «оба». Пропущена Б."]},{"author":"Е. Муравенко","question":"Даны формы глаголов в 1-м лице единственного числа: <em>вожу</em>, <em>лечу</em>, <em>молю</em>, <em>пою</em>. Какая форма однозначна, т. е. относится только к одному глаголу?","choices":["<em>вожу</em>","<em>лечу</em>","<em>молю</em>","<em>пою</em>","каждая из форм омонимична, может относиться к двум разным глаголам."],"key":"В","review":["Четыре формы глаголов","«Вожу» бывает от «водить» и «возить», «лечу» — от «лететь» и «лечить», «пою» — от «петь» и «поить».","«Молю» подходит только к «молить». От «молоть» было бы «мелю»."]},{"author":"А. Пучкова","question":"Даны предлоги <em>без</em>, <em>в</em>, <em>на</em> и <em>с</em>. Какие два из них могут быть соседними, причём не разделёнными знаком препинания, словами в предложении?","choices":["только <em>в</em> и <em>без</em>","только <em>с</em> и <em>в</em>","только <em>с</em> и <em>на</em>","ни одна пара из данных предлогов не может встречаться подряд","все пары из данных предлогов могут встречаться подряд."],"key":"Д","review":["Соседние предлоги","Один предлог может стоять перед всей группой, а другой — внутри неё: «в без меры яркой куртке», «в на первый взгляд обычном деле», «в с детства знакомом доме».","Можно также сказать «на без малого сотне страниц», «без с детства знакомого голоса» и «на с трудом занятом месте». Значит, все шесть пар могут встретиться."]},{"author":"И. Рубанов","question":"Перед вами — начало последовательности, в которой всего немногим более 30 чисел:\n<em>12222112218232…</em>\nКаково наибольшее число в этой последовательности?","choices":["8","9","10","11","12."],"key":"Г","review":["Последовательность чисел","Начало «1, 2, 2, 2, 2, 1, 1» совпадает с числом букв в названиях А, Б, В, Г, Д, Е, Ё. Число 8 дальше даёт «и краткое», в котором восемь букв.","Самое длинное название в алфавите — «твёрдый знак». В нём семь букв в первом слове и четыре во втором, всего одиннадцать."]}], {"year":2020,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2020-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
